// In-game gallery: arrows + chips drive the scroll-snap track (it also works by swipe / keyboard).
(function () {
  document.querySelectorAll('[data-cy-gallery]').forEach(function (g) {
    var tr = g.querySelector('.cy3-track'), sl = [].slice.call(tr.children);
    var prev = g.querySelector('.prev'), next = g.querySelector('.next');
    var dots = [].slice.call((g.parentNode.querySelector('.cy3-dots') || document).querySelectorAll('.cy3-dot'));
    var cur = 0, rm = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    function go(i) { i = Math.max(0, Math.min(sl.length - 1, i)); tr.scrollTo({ left: sl[i].offsetLeft - tr.offsetLeft, behavior: rm ? 'auto' : 'smooth' }); }
    function mark(i) { cur = i; prev.disabled = i === 0; next.disabled = i === sl.length - 1; dots.forEach(function (d, k) { d.setAttribute('aria-current', k === i ? 'true' : 'false'); }); }
    prev.addEventListener('click', function () { go(cur - 1); });
    next.addEventListener('click', function () { go(cur + 1); });
    dots.forEach(function (d) { d.addEventListener('click', function () { go(+d.getAttribute('data-i')); }); });
    var t; tr.addEventListener('scroll', function () { clearTimeout(t); t = setTimeout(function () { var w = sl[0].offsetWidth + 18; mark(Math.round(tr.scrollLeft / w)); }, 60); }, { passive: true });
    tr.addEventListener('keydown', function (e) { if (e.key === 'ArrowRight') { e.preventDefault(); go(cur + 1); } else if (e.key === 'ArrowLeft') { e.preventDefault(); go(cur - 1); } });
    mark(0);
  });
})();
'''
