  const rows = items
    .map(
      (item, i) =>
        `<tr>
          <td width="20" style="padding:0 0 ${i === items.length - 1 ? 0 : 10}px;font-family:${FONT};font-size:15px;line-height:1.65;color:${BRAND.violet};vertical-align:top;">&#8226;</td>
