/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
export function substitute(input: string, vars: Record<string, unknown>): string {
  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
    const v = vars[key];
    return v === undefined || v === null ? "" : String(v);
  });
}

/**
 * Minimal built-in defaults used when a template row is missing or disabled.
 * These are intentionally plain — the real, branded copy lives in the DB (see
 * `prisma/seed-email-templates.ts`).
 */
const DEFAULTS: Record<string, { subject: string; body: string }> = {
  welcome: {
    subject: "Welcome to Nxeon",
    body: `${emailHeading("Welcome, {{name}}!")}${emailParagraph("Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.")}`,
  },
  dedicated_server_ready: {
    subject: "Your bare metal server {{label}} is online",
    body: `${emailHeading("{{label}} is ready")}${emailParagraph("Your bare metal dedicated server is installed and online. Log in as root with the SSH key you chose. Primary IP: {{ip}}")}${emailButton("{{url}}", "Open your server")}`,
  },
  password_reset: {
    subject: "Reset your Nxeon password",
    body: `${emailHeading("Reset your password")}${emailParagraph("Use the button below to set a new password. It expires in 1 hour.")}${emailButton("{{resetUrl}}", "Reset password")}`,
  },
};

const GENERIC_FALLBACK = (key: string) => ({
  subject: "A message from Nxeon",
  body: `${emailHeading("Nxeon")}${emailParagraph(`This notification (<code>${esc(key)}</code>) has no configured template.`)}`,
});

export type RenderedEmail = { subject: string; html: string; template: string };

/**
 * Render a stored (or default) template for `key`, substituting `vars`,
 * returning the final subject and full wrapped HTML ready to send/preview.
 */
export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
  let subject: string;
  let body: string;

  let row: { subject: string; html: string; enabled: boolean } | null = null;
  try {
    row = await (await prisma()).emailTemplate.findUnique({
      where: { key },
      select: { subject: true, html: true, enabled: true },
    });
  } catch {
    row = null;
  }

  if (row && row.enabled) {
    subject = row.subject;
    body = row.html;
  } else {
    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
    subject = d.subject;
    body = d.body;
  }

  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
  return {
    template: key,
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars), { preheader }),
  };
}

/**
 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
 * editor's live preview and by the seed preview. Same wrapping as a real send.
 */
export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
  return {
    template: "draft",
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars), { preheader }),
  };
}

/* -------------------------------------------------------------------------- */
/*                   EmailLog: what may be kept, and for how long              */
/* -------------------------------------------------------------------------- */

/**
 * Query parameters whose VALUE is a bearer secret — possession of the string is
 * the whole authentication.
 *
 * WHY THIS EXISTS. Two flows put a live credential inside an email body:
 *
 *   lib/actions-account.ts     `${APP_URL}/reset-password?token=${token}`
 *   lib/email-verification.ts  `${base}/api/auth/verify-email?token=${token}`
 *
 * In both, `token` is the RAW `randomBytes(32).toString("base64url")` and only
 * its SHA-256 ever reaches the database — `PasswordResetToken.tokenHash` /
 * `EmailVerificationToken.tokenHash`. That hashing is the entire reason those
 * columns are shaped the way they are, and `EmailVerificationToken`'s own schema
 * comment states the guarantee it buys: "a database leak hands out no working
 * links."
 *
 * `recordEmail` then wrote the rendered body — raw link and all — straight into
 * `EmailLog.html`, on EVERY path (`lib/mailer.ts` logs success, SMTP failure and
 * not-configured alike). One SELECT on `EmailLog` handed out working password
 * reset links for every account that had asked for one, which cancelled the
 * hashing outright: the token table was hardened and the audit log was not.
 * Same for a database backup, where nothing expires and no pruning ran.
 *
 * The redaction happens HERE, at the single choke point every message passes
 * through, rather than per template — a per-template rule is one someone can
 * forget the next time a token-bearing email is added, and nothing would fail.
 *
 * The admin preview keeps everything it exists for: layout, copy, styling,
 * deliverability. An operator debugging "did the reset mail render correctly"
 * needs to see that the link is present and well-formed, not to be able to walk
 * through it into a customer's account.
 */
const SECRET_QUERY_PARAM =
  /((?:\?|&amp;|&)(?:token|code|key|secret|otp|invite|auth|sig|signature|password|pw)=)[^&"'<>\s#]+/gi;

/** What a redacted value is replaced with. Visible, so nobody thinks it was empty. */
export const REDACTED = "[redacted]";

/**
 * Strip bearer secrets out of an email body before it is persisted.
 *
 * Applied to the STORED copy only — `lib/mailer.ts` hands the real HTML to the
 * SMTP transport first, so the message the customer receives is untouched and
 * their link still works.
 */
export function redactEmailSecrets(html: string): string {
  return String(html ?? "").replace(SECRET_QUERY_PARAM, `$1${REDACTED}`);
}

/**
 * Whether `url` carries one of the same bearer-secret query params
 * `redactEmailSecrets` strips. Used by lib/mailer.ts to decide which anchors
 * are safe to rewrite into click-tracking links — a secret-bearing href is
 * left untouched (not tracked) rather than have its real, working destination
 * stored in `EmailLog.links` for a plain unauthenticated redirect route to
 * serve back up. Builds a fresh RegExp each call: `SECRET_QUERY_PARAM` is
 * `/g`-flagged and `.test()` on a shared global regex carries `lastIndex`
 * state across calls, which would make this return wrong answers on reuse.
 */
export function containsSecretQueryParam(url: string): boolean {
  return new RegExp(SECRET_QUERY_PARAM.source, "gi").test(String(url ?? ""));
}

/**
 * How long an `EmailLog` row is kept. There was no retention at all: every
 * message ever sent was kept forever, which is what turned a rendering-preview
 * convenience into an indefinite archive of customer correspondence. 90 days is
 * long enough to debug a deliverability complaint and short enough that the log
 * is not a second copy of the customer database.
 */
export function emailLogRetentionDays(): number {
  const raw = Number(process.env.NXEON_EMAIL_LOG_RETENTION_DAYS ?? 90);
  if (!Number.isFinite(raw) || raw <= 0) return 90;
  return Math.min(Math.max(Math.floor(raw), 1), 3650);
}

/** The instant before which `EmailLog` rows are deleted, given `now`. */
export function emailLogCutoff(now: number = Date.now()): Date {
  return new Date(now - emailLogRetentionDays() * 24 * 60 * 60 * 1000);
}

/**
 * Opportunistic retention sweep — at most once an hour, never blocking a send,
 * never throwing. Same shape as the bucket sweep in lib/rate-limit.ts: no timer,
 * no cron row to forget to schedule, and it runs on the only event that can grow
 * the table.
 */
let lastPrune = 0;
const PRUNE_INTERVAL_MS = 60 * 60_000;
async function pruneEmailLog(now: number): Promise<void> {
  if (now - lastPrune < PRUNE_INTERVAL_MS) return;
  lastPrune = now;
  try {
    await (await prisma()).emailLog.deleteMany({
      where: { createdAt: { lt: emailLogCutoff(now) } },
    });
  } catch (e) {
    console.error("[email-render] EmailLog retention sweep failed:", e);
  }
}

/**
 * Append an `EmailLog` row for every send attempt. Never throws (logging must
 * not break a mail flow).
 *
 * The body is REDACTED before it is written — see `redactEmailSecrets`. Nothing
 * downstream re-reads a token out of this row, so redaction is lossless for
 * every purpose the log actually serves.
 */
export async function recordEmail(
  toEmail: string,
  subject: string,
  template: string | null,
  html: string,
  status: "SENT" | "FAILED",
  error?: string | null,
  userId?: string | null,
  /** Pre-generated id (lib/mailer.ts mints one so click/open tracking URLs can
   *  reference the row before it exists). Falls back to Prisma's own cuid(). */
  id?: string,
  /** Real destination URLs, positionally indexed — see the EmailLog.links doc
   *  comment in prisma/schema.prisma. Already excludes any secret-bearing href. */
  links?: string[] | null,
  /**
   * The `NotifyKind` (lib/prefs.ts) this send was classified as, if any — see
   * `sendMail`'s `opts.kind`. Persisted so `worker/critical-email-retry.ts` can
   * find a FAILED row whose kind is CRITICAL and retry it without re-deriving
   * the original template context. Omitted (null) for sends that never passed a
   * `kind`, which is most non-critical sends and every row written before this
   * column existed.
   */
  kind?: string | null,
): Promise<void> {
  try {
    await (await prisma()).emailLog.create({
      data: {
        ...(id ? { id } : {}),
        toEmail,
        subject: subject.slice(0, 500),
        template: template ?? null,
        html: redactEmailSecrets(html),
        status,
        error: error ? String(error).slice(0, 1000) : null,
        userId: userId ?? null,
        links: links && links.length ? links : undefined,
        kind: kind ?? null,
      },
    });
  } catch (e) {
    console.error("[email-render] failed to record EmailLog:", e);
  }
  await pruneEmailLog(Date.now());
}

   * Optional From override. Falls back to the admin `smtp_from` setting when
   * omitted (every existing transactional/marketing send is unaffected).
   * CAVEAT: the mail relay (Mailcow) enforces sender-address ownership per
   * authenticated SMTP user — an address the configured `smtp_user` doesn't
   * own gets rejected outright (553 5.7.1 "not owned by..."), so this only
   * works for addresses actually provisioned to that mailbox. For a support
   * reply that needs to look like it's from a different address, use
   * `replyTo` (see `supportReplyAddress()`) instead — it has no such
   * restriction.
   */
  from?: string;
  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
  replyTo?: string;
  /** Explicit subject. Optional when `template` is provided. */
  subject?: string;
  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
  html?: string;
  text?: string;
  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
  template?: string;
  /** Variables for `{{placeholders}}` when rendering from a template. */
  vars?: Record<string, unknown>;
  /** Attribution for the EmailLog row. */
  userId?: string | null;
  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
  invoiceId?: string;
  /** Extra attachments. */
  attachments?: MailAttachment[];
  /**
   * What KIND of message this is, for the notification-preference policy in
   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
   * the customer's choice centrally — see the gate below.
   *
   * Omitting it means "always send", which is the safe default: a message must
   * never be dropped because someone forgot to classify it.
   */
  kind?: NotifyKind;
  /**
   * When set, this is a MARKETING send and the message carries RFC 8058 one-click
   * unsubscribe headers pointing at this URL:
   *   List-Unsubscribe: <https://…/api/unsubscribe?token=…>
   *   List-Unsubscribe-Post: List-Unsubscribe=One-Click
   * Transactional sends never pass this, so they never get the headers. There is
   * no list-unsubscribe MAILBOX configured, so only the https one-click URL is
   * advertised (a mailto with no automation behind it would be worse than none).
   */
  listUnsubscribeUrl?: string;
};

/** Matches an anchor's href attribute value (double-quoted, http/https only —
 *  every template composes links via `appUrl()`/`path()`, never a bare mailto
 *  or relative href, so this is the complete surface). */
const HREF_RE = /href="(https?:\/\/[^"]+)"/g;

/**
 * Rewrite every trackable anchor in `html` to route through the click-redirect
 * endpoint, and append an invisible open-tracking pixel before `</body>`.
 *
 * An anchor is SKIPPED (left exactly as-is, not tracked) when its href carries
 * a bearer secret (password reset, email verification, invite tokens, …) —
 * see `containsSecretQueryParam`. The real destination for every rewritten
 * link is returned in `links`, positionally indexed to match the `/click/N`
 * URLs, for the caller to persist on the EmailLog row; a secret-bearing href
 * never enters that array, so it can never be re-served by the redirect route.
 */
export function injectEmailTracking(html: string, emailLogId: string): { html: string; links: string[] } {
  const links: string[] = [];
  const base = appUrl();
  let out = html.replace(HREF_RE, (full, href: string) => {
    // The outreach unsubscribe link must stay a direct link (never a tracked redirect, never a counted click).
    if (containsSecretQueryParam(href) || href.includes("/api/outreach/unsubscribe")) return full;
    const idx = links.length;
    links.push(href);
    return `href="${base}/api/track/email/${emailLogId}/click/${idx}"`;
  });
  const pixel = `<img src="${base}/api/track/email/${emailLogId}/open" width="1" height="1" alt="" style="display:block;border:0;outline:none;" />`;
  out = out.includes("</body>") ? out.replace("</body>", `${pixel}</body>`) : out + pixel;
  return { html: out, links };
}

/**
 * Send an email. Never throws — logs and returns false on failure so callers
 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
 * FAILED + error otherwise) for the admin Logs viewer.
 *
 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
 * `User.notificationPrefs` was a column the customer edited and nothing read, so
 * turning off "email me about billing" changed nothing. Gating each send site
 * individually would have fixed today's sites and left every future one to
 * re-introduce the bug; gating centrally means a new send site inherits the
 * policy automatically and per-site checks become defence in depth.
 *
 * Two deliberate properties, both fail-open:
 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
 *     the database, and also on a lookup error. A payment-failure or suspension
 *     warning must not be lost because a preference read failed.
 */
export async function sendMail(opts: SendMailOpts): Promise<boolean> {
  // Preference gate. CRITICAL kinds (payment failed, suspension, security
  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
  // -circuit to true, so this costs nothing on the paths that matter most.
  if (opts.kind && opts.userId) {
    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
    if (!allowed) {
      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
      return false;
    }
  }

  // Resolve subject/html: prefer explicit values, otherwise render the template.
  let subject = opts.subject ?? "";
  let html = opts.html ?? "";
  const templateKey = opts.template ?? null;

  if (templateKey && !opts.html) {
    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
    subject = opts.subject ?? rendered.subject;
    html = rendered.html;
  }

  // Plain-text fallback derived from the UNTRACKED html — a text-only client
  // shows real URLs, not opaque tracking-redirect ones.
  const derivedText = opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

  // Open/click tracking: mint the EmailLog id up front so the pixel + rewritten
  // link URLs baked into the outgoing HTML reference a row that exists by the
  // time anyone opens or clicks. Applied uniformly to every send; see
  // injectEmailTracking's own doc comment for what's deliberately excluded.
  const emailLogId = randomUUID();
  const tracked = injectEmailTracking(html, emailLogId);
  html = tracked.html;

  // Assemble attachments (invoice auto-attaches for the relevant templates).
  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
  if (wantInvoice && opts.invoiceId) {
    const att = await invoiceAttachment(opts.invoiceId);
    if (att) attachments.push(att);
  }

  try {
    const c = await loadSmtp();
    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
      console.warn("[mailer] not configured — skipping email:", subject);
      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId, emailLogId, tracked.links, opts.kind);
      return false;
    }
    const t = transport(c);
    // RFC 8058 one-click unsubscribe — MARKETING sends only (a `listUnsubscribeUrl`
    // is passed). Transactional sends omit it and get no such headers.
    const listHeaders = opts.listUnsubscribeUrl
      ? {
          "List-Unsubscribe": `<${opts.listUnsubscribeUrl}>`,
          "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
        }
      : undefined;
    await t.sendMail({
      from: opts.from || c.from,
      to: opts.to,
      replyTo: opts.replyTo || undefined,
      subject,
      html,
      text: derivedText,
      attachments: attachments.length ? attachments : undefined,
      ...(listHeaders ? { headers: listHeaders } : {}),
    });
    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId, emailLogId, tracked.links, opts.kind);
    return true;
  } catch (e) {
    console.error("[mailer] send failed:", e);
    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId, emailLogId, tracked.links, opts.kind);
    return false;
  }
}

/**
 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
 * and (for billing templates) attach the invoice. Thin convenience over
 * `sendMail` for new callers.
 *
 * `kind` is forwarded to `sendMail`, which is the ONLY place the notification
 * policy is enforced. It used to be absent from this signature, so every send
 * routed through this wrapper was structurally incapable of honouring the
 * customer's "Account email" preference — a caller could not have opted in even
 * if it wanted to. That is the same class of defect as the column nothing read
 * (see `sendMail`), just one layer up: the gate exists, and the convenient path
 * quietly walks around it. Omitting `kind` still means "always send".
 */
export async function sendTemplate(
  key: string,
  to: string,
  vars: Record<string, unknown> = {},
  opts: {
    userId?: string | null;
    invoiceId?: string;
    attachments?: MailAttachment[];
    kind?: NotifyKind;
  } = {},
): Promise<boolean> {
  return sendMail({
    to,
    template: key,
    vars,
    userId: opts.userId,
    invoiceId: opts.invoiceId,
    attachments: opts.attachments,
    kind: opts.kind,
  });
}

export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
  try {
    const c = await loadSmtp();
    const t = transport(c);
    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };

/**
 * Shared responsive email shell (inline styles for client compatibility).
 * Kept for the synchronous, code-rendered `emails.*` templates below and any
 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
 */
export function layout(title: string, body: string): string {
  // Delegate to the shared premium shell so every email is consistent.
  const heading = title
    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
    : "";
  return wrapEmail(`${heading}<div>${body}</div>`);
}

export function button(href: string, label: string): string {
  return emailButton(href, label);
}

// ---- Transactional templates ----
//
// The full transactional catalog lives in `lib/email-templates.ts` (30+
// templates, all composed from the shared inline-styled components). It is
// re-exported here as `emails` so every existing call site — `import { emails }
// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
// `{ template, subject, html }`; the six original signatures are preserved.
export type { BuiltEmail };

// ===========================================================================
// Card billing & dunning templates
//
// Renewals apply wallet credit first, then auto-charge the customer's saved
// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
// only suspend once the retries are exhausted. These templates carry that flow.
//
// They live here rather than in `lib/email-templates.ts` only because this file
// is the one owned by the card-billing change; they are built with the same
// `build()` shape and the same shared components, so they render identically to
// the rest of the catalog.
// ===========================================================================

/**
 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
 * so the worker's retry schedule and this copy must agree.
 */
export const DUNNING_RETRY_ATTEMPTS = 3;

/**
 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
 * module-private): eyebrow → heading → body blocks → single CTA → optional
 * footnote, wrapped with a preheader by the shared shell.
 */
function build(opts: {
  template: string;
  subject: string;
  preheader: string;
  eyebrow?: string;
  accent?: Accent;
  heading: string;
  blocks: string[];
  cta?: { href: string; label: string; accent?: Accent };
  note?: string;
}): BuiltEmail {
  const parts: string[] = [];
  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
  parts.push(emailHeading(opts.heading));
  parts.push(...opts.blocks);
  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
  if (opts.note) parts.push(emailNote(opts.note));
  return {
    template: opts.template,
    subject: opts.subject,
    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
  };
}

/** Masked card display used wherever we echo the saved card back. */
const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;

/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;

/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
const stillRunning = (hostname: string, extra = "") =>
  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");

const legacyPaymentFailed = catalogEmails.paymentFailed;
type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];

/**
 * Card charge declined — FIRST failure of the dunning sequence.
 *
 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
 * still used by the admin template previewer) keeps working alongside the new
 * renewal-dunning shape.
 */
function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
function paymentFailed(
  hostname: string,
  amountFormatted: string,
  last4: string,
  retryDateFormatted: string,
  billingUrl: string,
): BuiltEmail;
function paymentFailed(
  a: string | LegacyPaymentFailedArgs,
  amountFormatted?: string,
  last4?: string,
  retryDateFormatted?: string,
  billingUrl?: string,
): BuiltEmail {
  if (typeof a !== "string") return legacyPaymentFailed(a);
  const hostname = a;
  const amount = amountFormatted ?? "";
  const card = last4 ?? "";
  const retryDate = retryDateFormatted ?? "";
  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
  return build({
    template: "payment_failed",
    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
    eyebrow: "Payment issue",
    accent: "warn",
    heading: "We couldn't charge your card",
    blocks: [
      emailParagraph(
        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
      ),
      stillRunning(hostname),
      emailPanel(
        emailKeyValue([
          ["Server", hostname],
          ["Amount due", amount],
          ["Card", cardLabel(card)],
          ["Next attempt", retryDate],
        ]),
        "warn",
      ),
      emailParagraph(
        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
      ),
    ],
    cta: { href, label: "Update payment method", accent: "warn" },
    note: "If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.",
  });
}

