export const BRAND = {
  // Primary accent (buttons, gradient)
  violet: "#7c4dff",
  violetLight: "#9b7bff",
  violetDeep: "#5b2ee8",
  cyan: "#3edcf2",
  /** Readable-on-navy violet for TEXT (links, eyebrows, bullets). */
  link: "#a78bfa",
  // Surfaces
  pageBg: "#070a1a",
  card: "#0f1530",
  panel: "#141b3d",
  panelBorder: "#27306a",
  hair: "#232c55",
  // Ink
  ink: "#ffffff",
  body: "#b9c1e0",
  muted: "#8791b8",
  faint: "#6b749b",
  // Status (text/accent colours are the light variants so they read on navy)
  success: "#34d399",
  successBg: "#0d2b2a",
  warn: "#fbbf24",
  warnBg: "#2b2210",
  danger: "#f87171",
  dangerBg: "#2d1420",
  info: "#a78bfa",
  infoBg: "#1a1f4a",
};
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

export function appUrl(): string {
  return process.env.APP_URL ?? "https://nxeon.cloud";
}

const esc = (s: unknown) =>
  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/**
 * Make trusted inline markup readable on the navy card: anchors without their
 * own style get the link colour (default browser blue is unreadable on dark),
 * bare <b>/<strong> turn white. Pure string work, idempotent.
 */
function themeInline(html: string): string {
  return String(html ?? "")
    .replace(/<a\s+(?![^>]*\bstyle=)([^>]*?)>/gi, `<a $1 style="color:${BRAND.link};text-decoration:underline;">`)
    .replace(/<(b|strong)>/gi, `<$1 style="color:${BRAND.ink};">`);
}

/**
 * Legacy light-theme literals that still live in DB-stored template bodies
 * (EmailTemplate rows seeded before the dark theme). Mapped onto the new tokens
 * so an old row stays legible instead of rendering dark-on-dark.
 */
function remapLegacyColors(html: string): string {
  return html
    .replace(/color:\s*#6f47f5/gi, `color:${BRAND.link}`)
    .replace(/color:\s*#8a70fb/gi, `color:${BRAND.link}`)
    .replace(/color:\s*#15a34a/gi, `color:${BRAND.success}`)
    .replace(/color:\s*#1c1638/gi, `color:${BRAND.ink}`)
    .replace(/color:\s*#4a4763/gi, `color:${BRAND.body}`);
}

// ---------------------------------------------------------------------------
// Reusable, fully-inline email components. Every template composes these so the
// look stays consistent. All return an HTML string.
// ---------------------------------------------------------------------------

export type Accent = "violet" | "success" | "warn" | "danger" | "info";
const accentColor = (a: Accent = "violet") =>
  a === "success" ? BRAND.success : a === "warn" ? BRAND.warn : a === "danger" ? BRAND.danger : a === "info" ? BRAND.info : BRAND.link;
/** Solid button / bar colour (the saturated one, not the text-on-navy variant). */
const accentSolid = (a: Accent = "violet") =>
  a === "success" ? "#10b981" : a === "warn" ? "#d97706" : a === "danger" ? "#dc2626" : BRAND.violet;
const accentBg = (a: Accent = "violet") =>
  a === "success" ? BRAND.successBg : a === "warn" ? BRAND.warnBg : a === "danger" ? BRAND.dangerBg : BRAND.infoBg;
const DEFAULT_GLYPH: Record<Accent, string> = {
  violet: "&#9733;", // ★
  success: "&#10003;", // ✓
  warn: "!",
  danger: "&#10005;", // ✕
  info: "i",
};

/** Small uppercase eyebrow/kicker label above the headline. */
export function emailEyebrow(text: string, accent: Accent = "violet"): string {
  return `<div style="margin:0 0 10px;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:${accentColor(accent)};">${esc(text)}</div>`;
}

/**
 * Icon tile — a rounded, tinted square carrying one glyph (the mockup's icon
 * tiles). Glyphs are plain text/entities, not images: they render in every
 * client, with images blocked, and in dark mode. `glyph` is trusted markup.
 */
export function emailIconTile(glyph: string, accent: Accent = "violet", size = 52): string {
  const fs = Math.round(size * 0.46);
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;"><tr><td align="center" valign="middle" width="${size}" height="${size}" bgcolor="${accentBg(accent)}" style="width:${size}px;height:${size}px;background-color:${accentBg(accent)};border:1px solid ${BRAND.panelBorder};border-radius:${Math.round(size * 0.28)}px;font-family:${FONT};font-size:${fs}px;line-height:${size}px;font-weight:700;color:${accentColor(accent)};text-align:center;">${glyph}</td></tr></table>`;
}

/** Main headline. */
export function emailHeading(text: string): string {
  return `<h1 class="nx-h1" style="margin:0 0 14px;font-family:${FONT};font-size:28px;line-height:1.2;font-weight:800;letter-spacing:-0.4px;color:${BRAND.ink};">${esc(text)}</h1>`;
}

/** Body paragraph. `html` may contain trusted inline markup (links, <b>). */
export function emailParagraph(html: string): string {
  return `<p style="margin:0 0 16px;font-family:${FONT};font-size:15px;line-height:1.65;color:${BRAND.body};">${themeInline(html)}</p>`;
}

/** Small muted note (fine print, alternate-link fallback, etc). */
export function emailNote(html: string): string {
  return `<p style="margin:18px 0 0;font-family:${FONT};font-size:13px;line-height:1.6;color:${BRAND.muted};">${themeInline(html)}</p>`;
}

/** Bulletproof CTA button (padding-based + bgcolor so it survives Outlook). */
export function emailButton(href: string, label: string, accent: Accent = "violet"): string {
  const bg = accentSolid(accent);
  const grad = accent === "violet" ? `background-image:linear-gradient(90deg,${BRAND.violetDeep},${BRAND.violet} 45%,${BRAND.violetLight});` : "";
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:10px 0 6px;"><tr><td class="nx-btn" align="center" bgcolor="${bg}" style="border-radius:10px;background-color:${bg};${grad}">
    <a href="${href}" style="display:inline-block;padding:15px 34px;font-family:${FONT};font-size:15px;font-weight:700;line-height:1;color:#ffffff;text-decoration:none;border-radius:10px;">${esc(label)}&nbsp;&rarr;</a>
  </td></tr></table>`;
}

/** Soft rounded panel used to frame a details table / highlighted content. */
export function emailPanel(innerHtml: string, accent?: Accent): string {
  const leftRule = accent ? `border:1px solid ${BRAND.panelBorder};border-left:4px solid ${accentSolid(accent)};` : `border:1px solid ${BRAND.panelBorder};`;
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;background-color:${BRAND.panel};${leftRule}border-radius:14px;">
    <tr><td style="padding:18px 20px;">${innerHtml}</td></tr></table>`;
}

/** Colored status banner (e.g. suspended / payment failed / success). */
export function emailBanner(html: string, accent: Accent = "info"): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;background-color:${accentBg(accent)};border:1px solid ${BRAND.panelBorder};border-left:4px solid ${accentSolid(accent)};border-radius:14px;">
    <tr><td style="padding:14px 18px;font-family:${FONT};font-size:14px;line-height:1.55;color:${BRAND.ink};font-weight:600;">${themeInline(html)}</td></tr></table>`;
}

/** Key/value details table (two columns, hairline rows). Values may hold markup. */
export function emailKeyValue(rows: Array<[string, string]>): string {
  const body = rows
