          <td align="right" style="padding:11px 0 11px 16px;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:14px;font-weight:600;color:${BRAND.ink};vertical-align:top;">${themeInline(v)}</td>
