/** Monospace code / command block (e.g. an SSH command). */
export function emailCode(text: string): string {
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;background-color:${BRAND.pageBg};border:1px solid ${BRAND.panelBorder};border-radius:10px;">
