  const link = a.serverId ? `${appUrl()}/dashboard/servers/${a.serverId}` : `${appUrl()}/dashboard`;
  const lead = a.final ? "Your complimentary server ends tomorrow" : `Your complimentary server ends on ${when}`;
  const body =
    a.policy === "RENEW_WALLET"
      ? emailParagraph(`Your complimentary <b>${a.planName}</b> server is included free for its first term, which ends on <b>${when}</b>. After that it renews at the normal price — <b>${price}</b> — charged to your Nxeon wallet (or your saved card if the wallet doesn't cover it). If you don't want that, turn off auto-renew on the server's page before ${when}.`)
      : emailParagraph(`Your complimentary <b>${a.planName}</b> server's free term ends on <b>${when}</b>. Auto-renew is off, so <b>nothing will be charged</b> — but the server will be suspended when the term ends. To keep it, renew it from its page (${price}, from your wallet) before then.`);
  const html = wrapEmail([emailHeading(lead), body, emailButton(link, "Manage your server"), emailNote("You received this because Nxeon gave your partner account a free game server.")].join("\n"), { preheader: lead });
